INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(26700, 0, 267, 0, 0, 0, 'Hillsbrad Foothills', 'For all their green and pastoral beauty, the Hillsbrad Foothills have long been one of the most blood-soaked battlefields in Lordaeron. In the Second War the Horde fell upon the towns here, and afterward the fortress of Durnholde became the heart of the camps where defeated orcs were held, and where a young slave named Thrall was raised before he broke free. When the Third War left the north in ruins, the town of Hillsbrad and the port of Southshore were among the few human communities to survive. Now the Forsaken hold Tarren Mill, where High Executor Darthalia makes war on the humans while the apothecaries test their New Plague on the living. Southshore answers for the Alliance, and dwarves of Dun Garok guard the southeast. Neither side has the land to itself. The Syndicate, outlaws led by the fallen nobles of Alterac, lairs in the ruins of Durnholde, naga and murlocs crowd the beaches, and the ruins of Dalaran and the ogre-held mountains of Alterac lie to the north.', 'warcraft.wiki.gg/wiki/Hillsbrad_Foothills (most blood-soaked battlefield, Second War raids, Forsaken vs Southshore, Syndicate at Durnholde, naga, gnolls, murlocs); warcraft.wiki.gg/wiki/Durnholde_Keep (internment camp command center, Thrall); warcraft.wiki.gg/wiki/Hillsbrad_Fields (Hillsbrad and Southshore the only parts of Lordaeron not devastated); quest 527 description; quest 496 description; quest 541 description; quest 505 description; quest 545 description (ruined outskirts of Dalaran); quest 500 description (Crushridge ogres in the Ruins of Alterac)'),
(26701, 1, 267, 1, 0, 0, 'Southpoint Tower', 'At the far western end of the foothills, close by the road that climbs toward Silverpine Forest, stands Southpoint Tower, a ruined scout tower overlooking the western fields. Its broken walls still have a use. The Forsaken deathstalker Lesh keeps a lonely watch here, sent to survey the town of Hillsbrad and its fields from a distance. When the moment is right she sends word east to Tarren Mill in a coded phrase, the raven''s cry from the west doth beckon, and the Forsaken commanders take it as the signal that Hillsbrad is ripe for attack.', 'warcraft.wiki.gg/wiki/Southpoint_Tower (ruined scout tower at far west end, south of the Silverpine road, Deathstalker Lesh spying on the Alliance); quest 494 description and reward text; DB: Deathstalker Lesh 2214 stands in area 285; warcraft.wiki.gg/wiki/Southpoint_Tower (Lesh is female; DB model gender 1)'),
(26702, 1, 267, 2, 0, 0, 'Hillsbrad Fields', 'In the west of the foothills lie the orchards and pastures of Hillsbrad, one of the last human farming towns left in Lordaeron. Apple orchards, pumpkins and grazing cattle surround a small town hall, where Magistrate Burnside governs with a town council and his clerk, Horrace Whitesteed. Blacksmith Verringtan and his apprentices arm the townsfolk, and footmen stand guard. Farmer Ray and Farmer Getz own the northern farms, and Ray''s dog Stanley keeps him company. The town lives under siege. Raiders from Tarren Mill have marked its farmers, leaders and even its revered proclamation for destruction, and some townsfolk now strike back at the Forsaken from ambush.', 'warcraft.wiki.gg/wiki/Hillsbrad_Fields (apple orchards, pumpkins, cows, Burnside, council, clerk, Verringtan arming militia, ambushes); quests 527, 528, 529, 532, 567 descriptions; quest 502 description (Farmer Ray''s little dog Stanley); DB spawns in area 286: Burnside 2335, Whitesteed 2448, Verringtan 2404, Ray 232, Getz 2403, Stanley 2274, Hillsbrad Footman 2268, Councilman 2387; gameobjects Hillsbrad Proclamation 1761, Town Registry 1759'),
(26703, 1, 267, 3, 0, 0, 'Azurelode Mine', 'Due south of Hillsbrad, the Azurelode Mine cuts into hills that belonged to Gilneas before the Greymane Wall was raised. Today it is worked by the miners of Hillsbrad under Foreman Bonds, with sentries posted to guard them, and its iron feeds the armories of the Alliance. That makes it a prize. The Forsaken war planners in Tarren Mill want it for their own soldiers, and one of its miners, Hackett, is wanted there for the death of a deathstalker. The mine yields more than ore: a crate of rare crystals from its depths, bound for Southshore, was recently seized on the road by Forsaken raiders.', 'warcraft.wiki.gg/wiki/Azurelode_Mine (part of Gilneas before the Greymane Wall, miners under Foreman Bonds, supplied iron to Alliance armories); quest 539 description and reward text; quest 567 description (Miner Hackett wanted for the murder of Deathstalker Fry); quest 9435 description and reward text; DB spawns in area 288: Foreman Bonds 2305, Hillsbrad Miner, Sentry, Foreman, Miner Hackett 2450'),
(26704, 1, 267, 4, 0, 0, 'Darrow Hill', 'Darrow Hill rises in the north of the foothills, beneath the high ground of the Headland on the Alterac border. It is wild country. Vicious gray bears and starving mountain lions prowl its slopes, and yetis come down from the caves above. Somewhere in these hills the wizard Helcular once kept a ritual lair, until a mob from Southshore found and killed him there; the yetis later overran it, and his apprentice believes one of the beasts now carries the dead wizard''s rod. Prospectors brave the hill for iron, mithril and truesilver, and for the Alterac granite found in its cave.', 'warcraft.wiki.gg/wiki/Darrow_Hill (northern Hillsbrad right under the Headland, Alterac Granite in the cave on the hill); quest 552 description (ritual lair in the hills, yeti overtook it, one of the beasts has the rod); DB spawns in area 1056: Vicious Gray Bear, Starving Mountain Lion, Cave Yeti, Ferocious Yeti; Iron, Mithril, Truesilver deposits, Alterac Granite; creature_loot_template: Helcular''s Rod 3708 drops from Cave Yeti 2248 and Ferocious Yeti 2249; warcraft.wiki.gg/wiki/Helcular (lynch mob from Southshore, killed during a ritual in a cave)'),
(26705, 1, 267, 5, 0, 0, 'Tarren Mill', 'Not long ago Tarren Mill was a thriving human town in the hills of Lordaeron. The Forsaken have since claimed it as their southernmost holding, and it shows the neglect of so many Forsaken places: withered orchards, weathered houses and an old church whose pews now seat the dead. Deathguards patrol the lanes. From here High Executor Darthalia directs the war on Hillsbrad and Southshore, Apothecary Lydon brews toxins for the Dark Lady''s New Plague, and captured farmers are kept in a room close by. Other peoples of the Horde gather here too, from the orc Krusk on the Warchief''s business to blood elf envoys sent to aid their new allies.', 'warcraft.wiki.gg/wiki/Tarren_Mill (once a thriving human town, Forsaken seized it, church, withered orchards, poor repair); warcraft.wiki.gg/wiki/Hillsbrad_Foothills (Sunwell Trilogy: still human after the Third War, then the Forsaken''s southernmost holding); quest 524 description (captured farmers next door); quest 9425 description and reward text (blood elves supporting the Forsaken); quest 498 description; DB spawns in area 272: Tarren Mill Deathguard x28, Captured Farmer 2284, Pew gameobjects, Advisor Duskingdawn 17092 (faction 1604)'),
(26706, 1, 267, 6, 0, 0, 'Southshore', 'Southshore began as a small fishing village and grew into a busy military port in the Second War, when the Horde captured it and the Alliance later rebuilt it. It remains one of the last pockets of human civilization in Lordaeron. Magistrate Henry Maleb governs the town, his predecessor killed by assassins, while Marshal Redpath leads the guard against the Forsaken of Tarren Mill, the Syndicate and the ogres of Alterac. Life goes on regardless. Folk travel from as far as Darkshire for Chef Jessen''s turtle bisque, Merideth Carlson breeds horses, Loremaster Dibbs pores over books saved from Alterac, and the dwarven Brewmeister Bilger takes old debts in moonshine. In the cemetery lies Helcular, a wizard the townsfolk killed.', 'warcraft.wiki.gg/wiki/Southshore (fishing village, Second War military port captured by the Horde and rebuilt, one of the few pockets of human civilization); quest 505 description; quest greeting 2263 (Redpath: the Horde, the Syndicate and the Ogres); quest 555 description (folks from Darkshire); quests 7645, 540; quest 647 (Brewmeister Bilger); quest 552 description (Helcular buried in Southshore cemetery); DB: Helcular''s Grave 1767 in area 271; Brewmeister Bilger 2705 faction 55 next to the inn'),
(26707, 1, 267, 7, 0, 0, 'Western Strand', 'West of Southshore, the Western Strand runs along the shore where the foothills meet the sea. It belongs to the Torn Fin murlocs, whose coastrunners, muckdwellers, tidehunters and oracles crowd its beaches and shallows, and a murloc called Scargil is sometimes seen among them. Marshal Redpath wants the creatures thinned before they trouble the town, though the officer he gave the task to regards hunting overgrown fish as beneath him. The Forsaken of Tarren Mill find a use for the murlocs too, for their apothecaries prize Torn Fin eyes in their brews. Wreckage drifts in the water offshore.', 'warcraft.wiki.gg/wiki/Eastern_Strand (complementary Western Strand further west); quest 536 description and reward text; quest 559 description; quest 515 description (torn fin eyes); DB spawns in area 295: Torn Fin Coastrunner, Muckdweller, Oracle, Tidehunter; Scargil 14276 rank 4; Schooner Wreckage pools'),
(26708, 1, 267, 8, 0, 0, 'Purgation Isle', 'Off the southwestern coast of the foothills lies Purgation Isle, an island that belonged to the kingdom of Kul Tiras before the First War. Nothing living holds it now. Its shores are haunted by condemned human and dwarf spirits that cannot find peace in death: paladins and justicars under a curse, clerics, monks and acolytes, and mages who writhe in torment. Who they were in life, and what crime or curse bound them to the island, is not recorded. The ogre necromancer Kormok is said to have delighted in calling these restless dead to do his bidding.', 'warcraft.wiki.gg/wiki/Purgation_Isle (Kul Tiras before the First War, condemned human and dwarf spirits unable to find peace, recent history unknown, Kormok); DB spawns in area 896: Cursed Paladin 7071, Cursed Justicar 7072, Condemned Cleric 7070, Monk 7069, Acolyte 7068, Writhing Mage 7075'),
(26709, 1, 267, 9, 0, 0, 'Nethander Stead', 'East of Southshore, south of Tarren Mill on the far side of the river, lies Nethander Stead, a farm that has passed out of human hands. Its fields now belong to the Mudsnout gnolls, a tribe found nowhere else, whose shamans move among the overgrown furrows, and a gnoll called Ro''Bark is sometimes seen among them. Something else has taken root in the abandoned fields: Mudsnout Blossoms, giant pale mushrooms with a horrible reek. Apothecary Lydon of Tarren Mill prizes them as the base of one of his deadliest elixirs, and considers them the one good thing the gnolls have ever done.', 'warcraft.wiki.gg/wiki/Nethander_Stead (farm east of Southshore, only location of the Mudsnout tribe, giant white mushrooms in the abandoned fields); quest 509 description and reward text (south of Tarren Mill, east of the river and Southshore; horrible reek; those filthy gnolls are good for something); DB spawns in area 289: Mudsnout Gnoll 2372, Mudsnout Shaman 2373, Ro''Bark 14278 rank 4, Mudsnout Blossom 1723'),
(26710, 1, 267, 10, 0, 0, 'Durnholde Keep', 'Southeast of Tarren Mill, across the river, stand the ruins of Durnholde Keep. After the Second War the fortress served as the command center of the internment camps where defeated orcs were held, under the self-absorbed drunkard Lieutenant General Aedelas Blackmoore. Here Blackmoore raised an orphaned orc infant as a slave and pit fighter and named him Thrall, and here Taretha Foxton helped him escape. Thrall later returned, slew Blackmoore and called on the spirit of the earth to bring the keep down. Its ruins now shelter the Syndicate: watchmen, rogues and shadow mages who gather the blood of innocents, while their jailors keep captured orcs in chains.', 'warcraft.wiki.gg/wiki/Durnholde_Keep (internment camp command center, Blackmoore, Thrall''s upbringing and escape with Taretha''s help, Thrall leveled it, Syndicate outpost); quest 498 description (southeast of Tarren Mill across the river); quest 1066 description; DB spawns in area 275: Syndicate Watchman, Shadow Mage, Rogue; Drull 2239 and Tog''thar 2238 with Locked ball and chain; Jailor Eston 2427 and Jailor Marlgen 2428; warcraft.wiki.gg/wiki/Durnholde_Keep (Spirit of the Earth leveled the fortress)'),
(26711, 1, 267, 11, 0, 0, 'Eastern Strand', 'Southeast of Southshore, the Eastern Strand belongs to the naga. Daggerspine shorehunters, shorestalkers, sirens and screamers have come up out of the sea to claim its beaches and shallows, and a naga called Lady Zephris is sometimes seen among them. Their arrival troubles more than the local garrison. Word has reached the Alliance High Command that the naga are a growing threat, and Marshal Redpath has ordered his lieutenant to deal with them. The Forsaken see opportunity instead: the apothecaries of Tarren Mill want daggerspine scales for their poisons.', 'warcraft.wiki.gg/wiki/Eastern_Strand (southeast coast, home of the Daggerspine naga on the beaches and in the water); quest 561 description; quest 562 description (Alliance High Command concerned about the naga); quest 515 description (daggerspine scales); DB spawns in area 294: Daggerspine Shorehunter, Shorestalker, Siren, Screamer; Lady Zephris 14277 rank 4'),
(26712, 1, 267, 12, 0, 0, 'Dun Garok', 'In the southeastern hills, set against Thoradin''s Wall, stands Dun Garok, a dwarven keep whose garrison helps protect the humans of Hillsbrad and the Azurelode Mine. Captain Ironhill commands its mountaineers, riflemen and priests, and its barracks keep kegs of Shindigger Stout on hand. The Forsaken loathe the dwarves'' presence. Darthalia has made the keep the last target of her campaign, and the dwarves give as good as they get: their scouts once raided a Deathguard''s camp and walked off with his sword. A Stormpike named Tamra is sometimes found within its walls.', 'warcraft.wiki.gg/wiki/Dun_Garok (dwarven keep in the southeastern hills, helped protect the humans and the Azurelode Mine, Forsaken loathed the dwarves); quest 541 description (barracks along Thoradin''s Wall, Captain Ironhill); quest 517 description (keg of Shindigger Stout); quest 547 description; DB spawns in area 290: Captain Ironhill 2304, Dun Garok Mountaineer, Rifleman, Priest, Tamra Stormpike 14275 rank 2, Keg of Shindigger Stout 1727'),
(26713, 1, 267, 13, 0, 0, 'Thoradin''s Wall', 'Along the eastern edge of the foothills runs Thoradin''s Wall, raised long ago by King Thoradin of Arathor near his capital of Strom to shield humanity from the Amani trolls. It still divides Hillsbrad from the Arathi Highlands, though the centuries have left it heavily damaged and in ruins, its great stones broken in many places. Gray bears and moss creepers wander beneath its shadow, and the dwarves of Dun Garok have built their barracks against it, so that the ancient barrier still shelters a garrison of the Alliance.', 'warcraft.wiki.gg/wiki/Thoradin''s_Wall (built by Thoradin near Strom against the Amani, separates Arathi from Hillsbrad, heavily damaged and in ruins in original WoW, has a gateway); quest 541 description (Dun Garok along Thoradin''s Wall); DB spawns in area 1057: Elder Gray Bear, Giant Moss Creeper'),
(26714, 2, 267, 1, 2, 0, 'High Executor Darthalia', 'High Executor Darthalia commands Tarren Mill under the direct authority of the dreadlord Varimathras and the Dark Lady. Her charge is to quell what she calls the human infestation until the apothecaries finish their New Plague, and she pursues it without mercy: farms raided, peasants hunted through the orchards, Hillsbrad''s blacksmith and magistrate marked for death, and Southshore to be razed once Hillsbrad falls. She also pays the bounties on Hillsbrad''s most dangerous townsfolk, on the Syndicate''s thugs and on the Syndicate noble Baron Vardus. She has no patience for idleness or chatter, and soldiers who loiter in Tarren Mill are reminded she can behead them for treason.', 'quest greeting 2215; npc_text 16667 (You will speak when spoken to); quests 494, 527, 528, 529, 532, 539, 541 descriptions and texts; quests 549, 566, 567; warcraft.wiki.gg/wiki/High_Executor_Darthalia (under Varimathras and Sylvanas, stop the spread of humans in Hillsbrad)'),
(26715, 2, 267, 2, 2, 0, 'Apothecary Lydon', 'Apothecary Lydon of the Royal Apothecary Society is, in the judgment of Master Apothecary Faranell, one of the Society''s most dedicated and skilled members. He is also profoundly gloomy. Fresh air and blooming flowers sour his mood, and only suffering brightens his day. He tests his elixirs on Umpi, the frog he calls his assistant, poisoning and reanimating her over and over, and he has sent a poisoned treat to Farmer Ray''s dog Stanley and a tainted keg to the farmers held captive in Tarren Mill. Fellow apothecaries across the Horde seek his help: he once brewed a toxin to sap the violence from the Venture Company in Stonetalon.', 'quest greeting 2216; quests 496, 499, 501, 502, 509, 513, 515, 517, 524 descriptions and texts; quests 1065, 1066 (toxin for Stonetalon); creature_text 2216, 2230; warcraft.wiki.gg/wiki/Apothecary_Lydon'),
(26716, 2, 267, 3, 2, 0, 'Krusk', 'Krusk is one of a party of orc warriors sent by Warchief Thrall to investigate the Syndicate in Hillsbrad and to recover an object from Durnholde Keep. The Syndicate surprised them in the ruins and overwhelmed them by sheer numbers. Krusk fought his way free, but his comrades Drull and Tog''thar were left in chains and their leader Gol''dir was carried off elsewhere. Now Krusk waits among the Forsaken of Tarren Mill, gathering any word of the captives and of the trinket the Warchief wants. The place weighs on him, for the Warchief was born and raised close by.', 'quest greeting 2229 (the place the Warchief was born and raised lies so close); quest 498 description and reward text; quests 503, 506, 508; warcraft.wiki.gg/wiki/Krusk'),
(26717, 2, 267, 4, 1, 0, 'Magistrate Henry Maleb', 'Henry Maleb came to Southshore as its new magistrate after his predecessor was assassinated. He was elated to win such a commission so early in his career, though he now wonders if he would have been better off shuffling papers in Stormwind. His suspicion fell at once on the Syndicate, the thieves led by the fallen nobles of Alterac, and papers taken from their camps proved him right: the brigands were planning an important mission against Southshore, and a sealed contract named Maleb himself as the next to die. He meets attackers defiantly, crying that they will never take back Alterac, or Southshore.', 'quest greeting 2276; quest 505 description and reward text; quests 510, 522 reward texts; quest 512 description; creature_text 2276'),
(26718, 2, 267, 5, 1, 0, 'Marshal Redpath', 'Marshal Redpath commands the defense of Southshore, and he has his hands full. The Horde holds Tarren Mill, the Syndicate prowls the hills, and the Crushridge ogres who seized the ruins of Alterac may yet push down into the foothills and arrive at Southshore''s front door. Redpath means to keep them at bay, posting bounties on ogres and sending fighters into the ruins to bloody the noses of the warmongers. Closer to home he wants the murlocs of the Western Strand culled and the naga of the Eastern Strand put down, though the officer he trusts with that work is far less eager than he is.', 'quest greeting 2263; quests 500, 504 descriptions and reward texts; quests 536, 561; DB: Redpath 2263 faction template 12 (Stormwind)'),
(26719, 2, 267, 6, 1, 0, 'Lieutenant Farren Orinelle', 'Lieutenant Farren Orinelle was transferred to Southshore from the Stormwind city guard, and he has not forgiven anyone for it. He passes his days at the inn calling for more ale, complaining about the smell of the harbor and mocking Marshal Redpath''s orders to clear out the murlocs, which he gladly leaves to others. He cannot even stomach fish anymore. When word came that Alliance High Command was worried about the naga, Farren saw his chance: proof of victories against the Daggerspine, carried quietly to his old mentor Major Samuelson, now captain of the Stormwind guard, might earn him a transfer home.', 'quests 536, 559, 561, 562, 563 descriptions, request and reward texts; warcraft.wiki.gg/wiki/Southshore (Farren at the inn mocking Redpath); DB: Farren 2228 faction template 12, spawned in the Southshore inn'),
(26720, 2, 267, 7, 1, 0, 'Phin Odelic', 'Phin Odelic leads a small band of adventurers who look into the strange happenings around Hillsbrad. His suspicions took hold when his cousin in Hillsbrad had to put down his dog Stanley, after the animal swelled to an unnatural size and savagely attacked anyone who came near. Phin is sure the undead are behind it, and he sent two of his companions, Quae and Kinelory, to spy on the Go''Shek Farm in the Arathi Highlands. They speak of him with deep affection, for since the plague he has given them the friends and family they never thought they would find again.', 'quest 659 description; quest 657 reward text (Quae: since the plague, friends or family); quest 661 reward text; DB: Phin 2711 faction template 12, in Southshore'),
(26721, 2, 267, 8, 1, 0, 'Loremaster Dibbs', 'Loremaster Dibbs keeps his books in Southshore, the town that lies closest to the ruins of Alterac. He mourns the knowledge lost when that kingdom fell and the ogres moved into its halls, and he works with Milton Sheaf of the Royal Library in Stormwind to recover the tomes that survive, keeping back one ancient book of troll lore, the Arm of Gri''lek, for his own study. Every scrap of strange writing that trickles down from the mountains lands on his desk. Ciphers beyond his skill go on to Prospector Stormpike in Ironforge. His old bones, he admits, would never survive the climb himself.', 'quests 538, 540, 542 descriptions and texts; quests 511, 514, 551, 554 descriptions and texts; DB: Dibbs 2277 faction template 12'),
(26722, 3, 267, 1, 2, 0, 'The Battle of Hillsbrad', 'Under orders from Varimathras, the Forsaken of Tarren Mill are to quell the humans of the foothills until the New Plague is ready. The signal comes from Deathstalker Lesh at Southpoint Tower: Hillsbrad is ripe for attack. High Executor Darthalia strikes first at the town''s food, sending raiders against the northern farms and their owners, Farmer Ray and Farmer Getz, then after the panicked peasants hiding in the southern orchards. When the townsfolk fight on, armed by Blacksmith Verringtan, the smith and his apprentices are slain and his iron carried off. Next fall Magistrate Burnside and his council, the town proclamation destroyed and the registry stolen. The registry names the Azurelode Mine as an Alliance source of iron, so Foreman Bonds and his miners die in turn. Last of all comes the dwarven barracks at Dun Garok and Captain Ironhill. Those who see the campaign through carry Darthalia''s commendation to the Undercity.', 'quests 494, 527, 528, 529, 532, 539, 541, 14351 descriptions and reward texts'),
(26723, 3, 267, 2, 2, 0, 'The Apothecary''s Elixirs', 'In Tarren Mill, Apothecary Lydon serves the Dark Lady''s hunger for a New Plague, one meant for humans and Scourge alike, through a series of ever crueler elixirs. Gray bear tongues and creeper ichor become the Elixir of Suffering, tried out on his frog Umpi. Mountain lion blood becomes the Elixir of Pain, fed to Farmer Ray''s dog Stanley, who swells into a raging beast. The Elixir of Agony takes longer. Mudsnout Blossoms from Nethander Stead are made into a composite, treated by Master Apothecary Faranell in the Undercity with his colloid of decay, then activated with naga scales, murloc eyes and troll''s blood. Poured into a keg of Shindigger Stout stolen from Dun Garok, the plagued brew is left on the rug for the captured farmers of Tarren Mill.', 'quests 493, 496, 499, 501, 502, 509, 513, 515, 517, 524 descriptions and texts; smart_scripts 2274 (Stanley becomes Enraged Stanley and attacks); quest 659 description (dog grew to immense size and attacked)'),
(26724, 3, 267, 3, 1, 0, 'Hints of a New Plague', 'Word of strange events in Hillsbrad has reached Phin Odelic in Southshore. His cousin''s dog grew to monstrous size and turned savage, and Phin suspects the undead. Two of his companions, Quae and Kinelory, went to watch the Go''Shek Farm in the Arathi Highlands, where there seemed to be more going on than met the eye, and had not checked in for days. Found at last, they told of a courier slipping out of a small house on the farm, likely carrying notes to Tarren Mill. The courier''s sealed folder revealed that a Forsaken, Apothecary Jorell, had been working on deadly experiments at Go''Shek. Under guard, Kinelory crept down to the farm and stole the research Jorell had not yet sent on, giving Phin his first real clue to what the Forsaken are brewing.', 'quests 657, 658, 659, 660, 661 descriptions and texts'),
(26725, 3, 267, 4, 2, 0, 'Taretha''s Gift', 'Warchief Thrall sent a band of orcs to Hillsbrad to investigate the Syndicate and recover something from Durnholde Keep. The Syndicate overwhelmed them. Krusk escaped to Tarren Mill, but Drull and Tog''thar were chained in the ruins and their leader Gol''dir vanished. Once the two warriors were freed, Syndicate papers taken from a camp to the north showed where Gol''dir was held, forced to haul and dig as a slave. He brought grave news. The Syndicate''s leader, Lord Aliden Perenolde, meant to put the orcs back in chains, as his father and his mentor Blackmoore had planned, and his mistress Elysa wore the very thing the Warchief sought: a necklace bearing a crescent moon, once given to Thrall by Taretha Foxton, the human girl who helped him escape Durnholde. With Perenolde slain at his manor by Lordamere Lake, the terrified Elysa gave it up gladly.', 'quests 498, 533, 503, 506, 507, 508 descriptions and texts; item 3498 Taretha''s Necklace (a crescent moon on a silver chain); warcraft.wiki.gg/wiki/Taretha''s_Necklace (Taretha gave it to Thrall; later held by Elysa, delivered to Krusk); warcraft.wiki.gg/wiki/Taretha''s_Necklace (Taretha gave Thrall the necklace when he escaped Durnholde)'),
(26726, 3, 267, 5, 2, 0, 'Helcular''s Revenge', 'Helcular was a wizard of the foothills who sought to become a lich. He was close to completing the change when a lynch mob from Southshore found his ritual lair in the hills, killed him, and buried him in their own cemetery. His apprentice, Novice Thaivand, now dwells among the Forsaken of Tarren Mill and has sworn that the rains of vengeance will fall on Southshore. First the wizard''s rod must be taken back from the yetis who overran the lair. Then it must be charged at the three ceremonial pyres Helcular made for his greatest spell: the Flames of Azel and Veraz in the Foothill Caverns, and the Flame of Uzel in a cave higher in the mountains. Driven into the grave in Southshore, the charged rod raises Helcular''s remains, which rise crying for revenge on the town that killed him.', 'quests 552, 553 descriptions and texts; creature_text 2433 (Helcular''s Remains: Southshore shall pay in blood); warcraft.wiki.gg/wiki/Helcular (mage, lich ritual, lynch mob from Southshore, Thaivand); DB: Flames of Azel 1768 and Veraz 1769 in area 1680, Uzel 1770 in area 1683'),
(26727, 3, 267, 6, 1, 0, 'Southshore and the Syndicate', 'Southshore''s last magistrate was assassinated, and though the killers were never found, his successor Henry Maleb is all but certain the Syndicate hired them. Strikes against Syndicate camps north and west of Tarren Mill turn up worse news. One seized list calls for masks, oil and poison for an important mission against Southshore, and Maleb concludes that the brigands have made war on his town. Raids on the ruins of Strahnbrad strip signet rings from the Alterac nobles who lead them, and a contract sealed in red wax reveals that Maleb himself is the next target, on the order of the cold and brutal Baron Vardus. Stranger still is an encrypted letter that Loremaster Dibbs passes to Prospector Stormpike in Ironforge. Decoded, it proves to be the work of Nagaz of the Argus Wake, a shadowy power that seems to stand behind the Syndicate itself. Baron Vardus and Nagaz both fall in the end, yet Nagaz proves to be only the servant of another, and how far the Argus Wake reaches no one can say.', 'quests 505, 510, 511, 512, 514, 522, 523, 525, 537 descriptions and texts; creature_text 2435 (Southshore Crier: assassins after the Magistrate again); warcraft.wiki.gg/wiki/Syndicate (Alterac nobles, Argus Wake secretly controlled the Syndicate)');
